import * as schedule from "./lib/schedule/index.mjs";

export function main(argv = process.argv) {
  const output = new OutputBuffer();

  try {
    const args = parseTest10Args(argv);

    schedule.clear();

    const job1 = schedule.every().seconds.do(() => null);
    output.log(job1);
    schedule.cancelJob(job1);
    output.log(schedule.getJobs().length);

