    schedule.clear();
    output.log(schedule.getJobs().length);

    const job4 = schedule.every().days.at(args.a).do(() => null);
    output.log(job4);

    const job5 = schedule.every().weeks.do(() => null);
    output.log(job5);
    output.log(schedule.getJobs().length);

    output.flushStdout();
    return 0;
  } catch (error) {
    if (error instanceof CliExit) {
      if (error.stdoutText) {
        process.stdout.write(error.stdoutText);
